export interface CacheStore {
  get(key: string): Promise<string | null>;
  set(key: string, value: string, ttlMs: number): Promise<void>;
  del(key: string): Promise<void>;
}

// In-process LRU with TTL. Swap for a Redis-backed CacheStore when running more than one instance.
export class MemoryStore implements CacheStore {
  private entries = new Map<string, { value: string; expiresAt: number }>();
  private maxEntries: number;

  constructor(maxEntries = 10_000) {
    this.maxEntries = maxEntries;
  }

  async get(key: string): Promise<string | null> {
    const entry = this.entries.get(key);
    if (!entry) return null;
    if (entry.expiresAt <= Date.now()) {
      this.entries.delete(key);
      return null;
    }
    // Re-insert to mark as most recently used.
    this.entries.delete(key);
    this.entries.set(key, entry);
    return entry.value;
  }

  async set(key: string, value: string, ttlMs: number): Promise<void> {
    this.entries.delete(key);
    this.entries.set(key, { value, expiresAt: Date.now() + ttlMs });
    if (this.entries.size > this.maxEntries) {
      this.entries.delete(this.entries.keys().next().value!);
    }
  }

  async del(key: string): Promise<void> {
    this.entries.delete(key);
  }
}

export interface ProfileCacheOptions {
  store?: CacheStore;
  ttlMs?: number;
}

export class ProfileCache<T> {
  private fetchProfile: (userId: string) => Promise<T>;
  private store: CacheStore;
  private ttlMs: number;
  private inflight = new Map<string, Promise<T>>();

  constructor(fetchProfile: (userId: string) => Promise<T>, opts: ProfileCacheOptions = {}) {
    this.fetchProfile = fetchProfile;
    this.store = opts.store ?? new MemoryStore();
    this.ttlMs = opts.ttlMs ?? 60_000;
  }

  async get(userId: string): Promise<T> {
    const key = this.key(userId);

    // A cache outage degrades to a miss, never to a failed request.
    const cached = await this.store.get(key).catch(() => null);
    if (cached !== null) return JSON.parse(cached) as T;

    // Concurrent misses for the same user share one upstream call.
    const pending = this.inflight.get(key);
    if (pending) return pending;

    const request: Promise<T> = this.fetchProfile(userId)
      .then(async (profile) => {
        // Skip the write if invalidate() ran while we were fetching.
        if (this.inflight.get(key) === request) {
          await this.store.set(key, JSON.stringify(profile), this.ttlMs).catch(() => {});
        }
        return profile;
      })
      .finally(() => {
        if (this.inflight.get(key) === request) this.inflight.delete(key);
      });

    this.inflight.set(key, request);
    return request;
  }

  // Call after any write to the profile (update, delete, avatar change, ...).
  async invalidate(userId: string): Promise<void> {
    const key = this.key(userId);
    this.inflight.delete(key);
    await this.store.del(key);
  }

  private key(userId: string): string {
    return `profile:v1:${userId}`;
  }
}
EOF
